import { mergeConfig } from "vitest/config";

import { sharedVitestConfig } from "../../vitest.shared.js";

export default mergeConfig(sharedVitestConfig, {
  // tsconfig keeps `jsx: "preserve"` for Next.js; tests need Vite to compile JSX.
  oxc: { jsx: { runtime: "automatic" } },
  // Resolve the `@/*` alias from tsconfig, as shadcn components import through it.
  resolve: { tsconfigPaths: true },
  test: {
    coverage: {
      // shadcn/ui components are generated by its pinned CLI. Per the testing
      // strategy, generated files are excluded from the percentage and
      // covered by execution (component and browser tests use them).
      exclude: ["components/ui/**"],
    },
    environment: "jsdom",
    setupFiles: ["./vitest.setup.ts"],
  },
});
